from svgkit import *
from webgl_figs import WIDE
F1,F2,F3,F4,F5=WIDE
tool_html=r'''<div class="ir-tool" id="ir-tool"><style>.ir-tool-verdict{margin:.75rem 0 0}.ir-tool-next{margin:.5rem 0 0;font-size:.9rem}</style><div class="ir-tool-head"><span class="ir-tool-eyebrow">WebGL and WebGPU check</span><button type="button" class="ir-btn-primary" id="ir-gl-run">Run the check</button></div><div id="ir-gl-out" aria-live="polite"></div><p class="ir-tool-note" id="ir-gl-note">The check runs in your browser: it asks for WebGL and WebGPU contexts, with and without the fail-if-slow setting, and reads the GPU name where your browser allows it. Nothing is sent or stored.</p></div>'''
tool_js=r'''<script>(function(){var b=document.getElementById('ir-gl-run'),o=document.getElementById('ir-gl-out'),n=document.getElementById('ir-gl-note');if(!b||!o||!n)return;
function e(s){return String(s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
var SW=/swiftshader|llvmpipe|softpipe|lavapipe|microsoft basic render|basic render driver|software/i;
function ctx(kind,strict){try{var c=document.createElement('canvas');return c.getContext(kind,strict?{failIfMajorPerformanceCaveat:true}:{})||null}catch(x){return null}}
function gpuName(gl){try{var x=gl.getExtension('WEBGL_debug_renderer_info');if(x)return String(gl.getParameter(x.UNMASKED_RENDERER_WEBGL)||'')}catch(x){}return ''}
function free(gl){try{var l=gl&&gl.getExtension('WEBGL_lose_context');if(l)l.loseContext()}catch(x){}}
function browser(){var u=navigator.userAgent||'';if(/Firefox\//.test(u)||/FxiOS\//.test(u))return'firefox';if(/Edg\//.test(u)||/EdgA\//.test(u))return'edge';if(/CriOS\//.test(u)||/Chrome\//.test(u))return'chrome';if(/Safari\//.test(u)&&/Version\//.test(u))return'safari';return'other'}
function row(k,v){return '<div class="ir-tool-row"><dt>'+e(k)+'</dt><dd>'+e(v)+'</dd></div>'}
function webgpu(){return new Promise(function(res){if(!navigator.gpu){res(window.isSecureContext===false?'needs a secure (https) page':'not available in this browser');return}var d=false,t=setTimeout(function(){if(!d){d=true;res('could not be checked (timed out)')}},4000);
try{navigator.gpu.requestAdapter().then(function(a){if(d)return;d=true;clearTimeout(t);res(!a?'no adapter found':(a.isFallbackAdapter?'software adapter found':'adapter found'))},function(){if(d)return;d=true;clearTimeout(t);res('could not be checked')})}catch(x){if(!d){d=true;clearTimeout(t);res('could not be checked')}}})}
function steps(br,state){var s={chrome:'Turn on Use graphics acceleration when available in Settings, System (older versions: Use hardware acceleration when available), relaunch, then open chrome://gpu.',edge:'Turn on Use graphics acceleration when available in Settings, System, restart Edge, then open edge://gpu.',firefox:'Turn on hardware acceleration in Settings, Performance, check that webgl.disabled is false in about:config, and read the Graphics table in about:support.',safari:'WebGL is on by default in current Safari. Update macOS or iOS and Safari, then run the check again.',other:'See the section for your browser below.'};return s[br]||s.other}
function run(){b.disabled=true;n.textContent='Checking...';o.textContent='';
var g2s=ctx('webgl2',true),g1s=ctx('webgl',true)||ctx('experimental-webgl',true),g2=g2s||ctx('webgl2',false),g1=g1s||ctx('webgl',false)||ctx('experimental-webgl',false),any=g2||g1,name=any?gpuName(any):'',sw=!!(name&&SW.test(name)),hw=!!(g2s||g1s)&&!sw,state=!any?'none':(hw?'hardware':'software'),v,br=browser(),h='';
h+=row('WebGL 2',g2?'available':'not available')+row('WebGL 1',g1?'available':'not available');
h+=row('Hardware rendering',!any?'no WebGL context':(hw?'yes':'no, software rendering'));
h+=row('GPU name',name?name:(any?'hidden by the browser':'not available'));
if(state==='hardware'){v=g2?'WebGL 2 is running on your GPU. If a site still shows an error, the cause is probably that site or WebGPU, see below.':'WebGL 1 works, but WebGL 2 does not. Update your browser and graphics driver, then run the check again.'}
else if(state==='software'){v='WebGL is running in software, not on your GPU. This usually means graphics acceleration is off or the GPU is blocklisted. Next: '+steps(br,state)}
else{v='No WebGL context could be created. Next: '+steps(br,state)}
free(g2s);free(g1s);if(g2!==g2s)free(g2);if(g1!==g1s)free(g1);
o.innerHTML='<dl>'+h+'<div class="ir-tool-row" id="ir-gl-gpu"><dt>WebGPU</dt><dd>checking...</dd></div></dl><p class="ir-tool-verdict"><strong>'+e(v)+'</strong></p>';
webgpu().then(function(t){var el=document.getElementById('ir-gl-gpu');if(el)el.innerHTML='<dt>WebGPU</dt><dd>'+e(t)+'</dd>';n.textContent=(t==='no adapter found'||t==='software adapter found')?'WebGPU found no hardware adapter. If a site reports "found no usable graphics adapter", see the WebGPU section below.':'Nothing from this check is stored or sent by IntelReap.'}).then(function(){b.disabled=false;b.textContent='Run again'})}
b.addEventListener('click',run)})();</script>'''
S=dict(slug='how-to-enable-webgl',dir='guides',date='2026-06-26',date_label='',plan='A10',tool_html=tool_html,tool_js=tool_js,
title='How to Enable WebGL (and Fix WebGL Not Working)',headline='How to Enable WebGL and Fix WebGL Not Working: A Live Check, Browser Steps and WebGPU Errors',
desc='Check whether WebGL and WebGPU work in your browser, then fix it in Chrome, Edge, Firefox or Safari: graphics acceleration, GPU blocklists and error messages.',
kw=['how to enable webgl','webgl not working','enable webgl chrome','enable webgl firefox','webgl not supported','webgl is not available','a webgl context could not be created','webgl.force-enabled','override software rendering list','found no usable graphics adapter','webgpu found no usable graphics adapter chrome','chrome://gpu','webgl 2 not supported','how to enable webgl in firefox','turn on webgl chrome','hardware acceleration webgl'],about='WebGL',section='Browser Guides',crumb='How to Enable WebGL',
h1='How to Enable <span class="ndic-highlight">WebGL</span>',tagline='Run a live WebGL and WebGPU check, then follow the fix for your browser, including "found no usable graphics adapter" errors.',kicker='Browser Guides',cta='Run the Check',
qa_title='WebGL is on by default, so fix what blocks it',
qa_body='WebGL is on by default, so a failure usually means graphics acceleration is off, the GPU is blocklisted, or a driver is outdated. Run the check below, then follow the steps for your browser. WebGPU errors such as "found no usable graphics adapter" have the same causes.',
og_title='Enable <span style="color:#38bdf8">WebGL</span>',og_sub='Live check and fixes for every browser',og_chip='WebGL: <span style="color:#38bdf8">hardware</span>',
card_desc='Check whether WebGL and WebGPU work in your browser, then fix it in Chrome, Edge, Firefox or Safari: acceleration, blocklists and error messages.',
panel=dict(eyebrow='Graphics panel',h3='See what your browser reports about your GPU',p='The check above tests whether WebGL works. The <a href="/intelligence/graphics">Graphics panel</a> shows the WebGL version, GPU renderer and supported extensions your browser reports.',href='/intelligence/graphics',btn='Open Graphics'),
sections=[
('test','Run the WebGL and WebGPU Check',r'''<p>Run the check above in the browser that shows the problem. It asks for WebGL contexts the way a web app does, once with the fail-if-slow setting and once without, so it can tell WebGL on the GPU from WebGL in software. It also asks WebGPU for an adapter.</p>'''+fig(F1,'')+table('What the result means',['Result','What it means'],[['WebGL 2 on the GPU','Working. If a site still fails, the problem is that site or WebGPU.'],['WebGL 1 only','WebGL 2 did not open. Update the browser and graphics driver.'],['Software only','WebGL runs on the CPU. Graphics acceleration is off or the GPU is blocklisted.'],['No WebGL context','Nothing opened. Fix the browser setting or the driver first.'],['WebGPU: no adapter found','WebGPU found no usable GPU. See the WebGPU section.'],['GPU name hidden','The browser is hiding it. Firefox does this when privacy.resistFingerprinting is on.']])),
('why','Why WebGL Fails',r'''<p>WebGL is on by default in current browsers, so a failure almost always comes from something that sits between the page and the GPU. The browser checks a blocklist of graphics drivers it does not trust, then needs graphics acceleration turned on, then needs a working driver that can reach a GPU.</p>'''+fig(F2,'')+r'''<p>Each step has its own fix. A blocklisted driver is fixed by updating the driver or, as a last resort, overriding the list. A setting that is off is fixed in the browser. A missing or outdated driver is fixed by installing one from the maker. A remote desktop or virtual machine often has no GPU to reach, which we treat as general practice, not a sourced rule.</p><p>If you are not sure what a GPU does, <a href="/learn/what-is-a-gpu">What Is a GPU?</a> explains it.</p><p>For problems beyond the browser, such as a failing card, see the <a href="/guides/gpu-troubleshooting-guide">GPU troubleshooting guide</a>.</p>'''),
('chrome','Chrome and Edge',r'''<p>Chrome and Edge share the same engine and the same fixes.</p>'''+fig(F3,'')+r'''<ol><li>Open Settings, then System, and turn on <strong>Use graphics acceleration when available</strong>. Older versions call it Use hardware acceleration when available. Relaunch the browser.</li><li>Open <code class="ir-code">chrome://gpu</code> (<code class="ir-code">edge://gpu</code> in Edge) and read the WebGL line. Hardware accelerated is what you want. Software only means the browser fell back to the CPU, and the Problems Detected list explains why.</li><li>If the GPU is blocklisted, open <code class="ir-code">chrome://flags/#ignore-gpu-blocklist</code> and set Override software rendering list to Enabled, then relaunch. Use it to test, not as a permanent fix.</li><li>Update the GPU driver from NVIDIA, AMD or Intel, or through your computer maker.</li></ol><p>The Edge addresses follow the same pattern but are not documented by Microsoft in the sources we checked.</p>'''),
('firefox','Firefox',r'''<p>Firefox has its own blocklist and its own preferences.</p>'''+fig(F4,'')+r'''<ol><li>Open Settings, General, Performance. Clear <strong>Use recommended performance settings</strong> to reveal <strong>Use hardware acceleration when available</strong>, and make sure it is ticked. Newer versions may place this under Tabs and browsing. Restart Firefox.</li><li>Type <code class="ir-code">about:config</code>, accept the warning and search for <code class="ir-code">webgl.disabled</code>. It should be false.</li><li>Open <code class="ir-code">about:support</code> and read the Graphics table. The WebGL 1 and WebGL 2 driver renderer lines should name your GPU, and a blocked driver says so.</li><li>As a last resort, set <code class="ir-code">webgl.force-enabled</code> to true.</li></ol><p>Mozilla's wiki says to force-enable a blocked feature at your own risk, and that if forcing it does not work your hardware probably does not support it. A Mozilla bug thread from Firefox 68 says only WebGL 1 could be forced then, so it may not help with WebGL 2.</p><p>If Firefox crashes or draws wrongly, Mozilla's guidance is to update your graphics driver and, if that fails, to turn off hardware acceleration and then WebGL (set <code class="ir-code">webgl.disabled</code> to true).</p>'''),
('safari','Safari',r'''<p>WebGL is on by default in current Safari. A vendor help page says WebGL is enabled by default from Safari 15.1, and that the only way to turn it on or off is the terminal. Older Safari versions had a WebGL 2.0 switch under Develop, Experimental Features. Newer macOS versions show Feature Flags in Settings, Advanced, after you tick Show features for web developers. If WebGL fails in Safari, update macOS or iOS and Safari first, because settings are rarely the cause.</p><p>These Safari details come from support pages of other companies, not from Apple, so treat them as the weakest part of this guide.</p>'''),
('webgpu','"Found No Usable Graphics Adapter" (WebGPU)',r'''<p>Many web apps and games show a message such as "found no usable graphics adapter" when WebGPU cannot get a GPU. It is a WebGPU message, not a WebGL one, but the causes overlap.</p>'''+fig(F5,'')+r'''<p>Chrome's own WebGPU troubleshooting page lists the reasons, in this order:</p><ol><li>Graphics acceleration is off in <code class="ir-code">chrome://settings/system</code>.</li><li>The platform is not supported. WebGPU needs Chrome 113 or later on ChromeOS, macOS and Windows, Chrome 121 or later on Android, and a secure (https) page.</li><li>The GPU is blocklisted. <code class="ir-code">chrome://gpu</code> then says WebGPU has been disabled via blocklist or the command line, and the <code class="ir-code">chrome://flags/#ignore-gpu-blocklist</code> and <code class="ir-code">chrome://flags/#enable-unsafe-webgpu</code> flags can override it for testing.</li><li>No adapter matches the options the app asked for.</li><li>There is no GPU, hardware or software-emulated. <code class="ir-code">chrome://gpu</code> should read WebGPU: Hardware accelerated. If it reads Software only, update the GPU driver.</li><li>The GPU process crashed several times. Reload the page or restart Chrome.</li></ol><p>Mozilla shipped WebGPU on Windows in Firefox 141, and other platforms followed later or are still in progress, so an older or non-Windows Firefox may not have it. Firefox keeps its own blocklist, which the <code class="ir-code">gfx.webgpu.ignore-blocklist</code> preference overrides for testing.</p>'''),
('context','"A WebGL Context Could Not Be Created"',r'''<p>This error means the browser tried to open WebGL and the graphics stack refused. Work through these in order and run the check after each:</p><ol><li>Turn on graphics acceleration in the browser.</li><li>Update the GPU driver.</li><li>Check whether the GPU is blocklisted: <code class="ir-code">chrome://gpu</code> in Chrome and Edge, <code class="ir-code">about:support</code> in Firefox.</li><li>Try a different browser. Each browser keeps its own blocklist, so one can work where another fails.</li><li>If you are in a remote desktop or virtual machine, it may have no GPU to give the browser.</li></ol>'''),
('messages','Common Error Messages and What They Mean',r'''<p>Web apps write their own messages, so the wording varies. This table matches the common ones to a first step.</p>'''+table('Messages and first steps',['Message','Likely cause','First step'],[['WebGL is unavailable, or WebGL is not supported','No WebGL context opened','Run the check, then turn on graphics acceleration'],['Your browser does not support WebGL 2, or WebGL2 is unavailable','WebGL 2 did not open','Update the browser and driver, then run the check'],['WebGL has been disabled via blocklist or the command line (Disabled Features: webgl)','The GPU or driver is blocklisted','Update the driver, then try the override for your browser'],['WebGL: Software only, hardware acceleration unavailable','WebGL is running on the CPU','Turn on acceleration and update the driver'],['Found no usable graphics adapter','WebGPU found no GPU','See the WebGPU section'],['Missing WEBGL_compressed_texture_s3tc, OES_texture_float_linear or other extensions','The context did not offer a required extension','Run the check, update the driver, or try another browser'],['webgl.force-enabled','A Firefox preference that overrides the blocklist','See the Firefox section for the warning'],['Override software rendering list','A Chrome flag that overrides the blocklist','See the Chrome section'],['Unable to create WebGL context','The browser could not open WebGL','Work through the context error steps']])),
('verify','How to Verify WebGL Is Working',r'''<p>Use any of these:</p><ol><li>The check at the top of this page, which also tells hardware from software.</li><li>get.webgl.org, a test page that shows a spinning cube when WebGL works.</li><li>The browser console: <code class="ir-code">!!document.createElement('canvas').getContext('webgl')</code> returns true when WebGL 1 opens, and the same with <code class="ir-code">'webgl2'</code> tests WebGL 2.</li></ol><p>The <a href="/intelligence/capability">Capability panel</a> lists WebGL beside the rest of what your browser reports.</p>'''),
],
logic="Separate three things that look alike: WebGL missing, WebGL running in software, and a WebGPU error. Test them in the browser with the same contexts a web app uses, then send the reader to the one fix that matches, instead of one list of steps for everything.",
method="The check runs in your browser. It requests WebGL 2 and WebGL 1 contexts with and without the failIfMajorPerformanceCaveat setting, reads the renderer string through the debug renderer extension where the browser allows it, treats names such as SwiftShader, llvmpipe and Basic Render Driver as software, and asks WebGPU for an adapter. It stores and sends nothing. Browsers may hide the renderer, and a context that opens only without the fail-if-slow setting is reported as software. The Chrome and WebGPU causes follow Chrome's own troubleshooting page. Weaker, stated here: the Safari details come from other companies' support pages, the Edge addresses and the Firefox Performance menu location come from secondary guides, the Firefox about:support line names are from a secondary guide, the Firefox macOS WebGPU status is from a bug thread, and the remote desktop and virtual machine point is general practice. The get.webgl.org description comes from older guides and we did not open that page. We did not test the steps on real machines.",
cites=[("Chrome for Developers: WebGPU troubleshooting tips and fixes",'https://developer.chrome.com/docs/web-platform/webgpu/troubleshooting-tips'),("Chrome for Developers: WebGPU overview and browser support",'https://developer.chrome.com/docs/web-platform/webgpu/overview'),("Mozilla Support: Upgrade your graphics drivers to use hardware acceleration and WebGL",'https://support.mozilla.org/kb/upgrade-graphics-drivers-use-hardware-acceleration'),("Mozilla wiki: Blocklisting and blocked graphics drivers",'https://wiki.mozilla.org/Blocklisting/Blocked_Graphics_Drivers'),("Mozilla Bugzilla 1563854: WebGL blocklisted for an open source driver",'https://bugzilla.mozilla.org/show_bug.cgi?id=1563854'),("Mozilla Gfx Team: Shipping WebGPU on Windows in Firefox 141",'https://mozillagfx.wordpress.com/2025/07/15/shipping-webgpu-on-windows-in-firefox-141/'),("Mozilla Bugzilla 1814745: WebGPU preference changes",'https://bugzilla.mozilla.org/show_bug.cgi?id=1814745'),("MDN: WEBGL_debug_renderer_info extension",'https://developer.mozilla.org/en-US/docs/Web/API/WEBGL_debug_renderer_info'),("Microsoft: Making your WebGL code more flexible",'https://learn.microsoft.com/en-us/archive/blogs/ie/making-your-webgl-code-more-flexible'),("WeVideo Help: How can I enable WebGL?",'https://support.wevideo.com/hc/en-us/articles/225259448-How-to-enable-WebGL'),("AllTrails Help: Why am I seeing a MapboxGL error",'https://support.alltrails.com/hc/en-gb/articles/360051234912-Why-am-I-seeing-a-MapboxGL-error')],
faq_sub='Thirteen questions about enabling WebGL, the error messages and WebGPU.',
faq=[("How do I enable WebGL in Chrome?","WebGL is on by default. If it fails, open Settings, then System, turn on Use graphics acceleration when available (older versions: Use hardware acceleration when available), relaunch, and check chrome://gpu. If the GPU is blocklisted, update the driver first."),
("How do I enable WebGL in Firefox?","Turn on hardware acceleration in Settings, Performance, check that webgl.disabled is false in about:config, and read the Graphics table in about:support. webgl.force-enabled is a last resort, at your own risk."),
("How do I enable WebGL in Safari?","WebGL is on by default in current Safari. If it fails, update macOS or iOS and Safari. Older versions had a WebGL 2.0 switch under Develop, Experimental Features."),
("How do I enable WebGL in Edge?","Edge follows Chrome: turn on graphics acceleration in Settings, System, restart Edge and check edge://gpu. The addresses follow Chrome's pattern but Microsoft's documentation did not confirm them in the sources we checked."),
("Is WebGL on by default?","Yes in current browsers. When it fails, the cause is usually a blocklisted driver, graphics acceleration turned off, an outdated driver, or no GPU, as in a remote session."),
("Why does it say a WebGL context could not be created?","The browser tried to open WebGL and the graphics stack refused. Turn on graphics acceleration, update the driver, check the blocklist and try another browser."),
("What does WebGL: Software only mean?","In chrome://gpu it means WebGL is running on the CPU, not the GPU. Check that graphics acceleration is on, read the Problems Detected list and update the driver."),
("Why does a site say found no usable graphics adapter?","It is a WebGPU message. WebGPU could not get a GPU. Chrome's troubleshooting page lists the causes, from a disabled setting to a blocklist or repeated GPU crashes. See the WebGPU section."),
("Is webgl.force-enabled safe?","Mozilla says to use it at your own risk, and that it may not work if the hardware does not support the feature. Use it for testing, then update the driver."),
("Why does WebGL fail in a remote desktop or virtual machine?","They often have no GPU to give the browser. That is general practice, not a sourced rule, so run the check on the real machine to compare."),
("Why does WebGL work in one browser but not another?","Each browser keeps its own blocklist and settings, so a driver can be blocked in one and allowed in another."),
("How do I test whether WebGL works?","Use the check at the top of this page, which also tells hardware from software, or open get.webgl.org and look for a spinning cube."),
("Does this check store anything?","No. It runs in your browser, sends nothing and stores nothing."),
],
)
